(()=>{'use strict';const root=document.querySelector('#moreLabs'),M=ScienceModels,Q=s=>root.querySelector(s),reduce=matchMedia('(prefers-reduced-motion: reduce)');let gen=0,p=.5,history=[.5],timer=null;const state={environment:'A',selection:.5};const T=(x,y,s,size=16)=>`<text x="${x}" y="${y}" text-anchor="middle" font-size="${size}" fill="#183047">${s}</text>`,line=(x,y,a,b)=>`<path d="M${x} ${y}L${a} ${b}" stroke="#183047" stroke-width="2" fill="none"/>`,circle=(x,y,r,c)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${c}"/>`;
root.innerHTML=`<div class="sectionhead"><div><p class="eyebrow">03 / EVOLUTION</p><h2>Watch a population change</h2></div><span class="pill">2026 TERM 4 OBJECTIVES</span></div><div class="labgrid"><div class="labvisual"><div id="exCanvas"></div><p id="exReadout" aria-live="polite"></p><div class="exinputs"><label>Environment favours <select id="ex-environment"><option value="A">A allele</option><option value="a">a allele</option><option value="neutral">Neither allele</option></select></label><label>Selection strength <input id="ex-selection" type="range" min="0" max="0.9" step="0.1" value="0.5"><output id="selectionValue">0.5</output></label></div><div class="controls"><button id="exPlay">▶ Play generations</button><button id="exStep">Next generation</button><button id="exReset">Reset population</button></div><p id="exLimit" class="small"></p></div><aside class="labnotes"><h3>Selection acts on inherited variation</h3><div class="reviewbox"><b>Predict first</b><p>What happens to allele A if the environment begins to favour allele a?</p></div><p id="exExplain"></p><details><summary>Check your prediction</summary><p>Relative reproductive success changes with the environment. The previously favoured allele can become less common over generations. Individuals do not change their inherited alleles because they need to.</p></details><p class="small">Objective: explain variation, selection pressure, differential reproduction and changing allele frequencies.</p>${WatchLearn.inline('evolution')}<button id="exQuiz" class="primary">Practise evolution questions →</button></aside></div>`;
function display(c,label,readout,explain,limit){Q('#exCanvas').innerHTML=`<svg viewBox="0 0 600 340" role="img" aria-label="${label}">${c}</svg>`;Q('#exReadout').textContent=readout;Q('#exExplain').textContent=explain;Q('#exLimit').textContent=limit;}
function evolution(){let c=T(155,25,'Expected genotype proportions',17),nAA=Math.round(p*p*60),nAa=Math.round(2*p*(1-p)*60);for(let i=0;i<60;i++){let col=i<nAA?'#002D72':i<nAA+nAa?'#d1ad52':'#2E6EA6';c+=circle(35+(i%10)*25,60+Math.floor(i/10)*32,9,col);}c+=T(155,275,'AA navy · Aa ochre · aa blue',13)+line(335,60,335,250)+line(335,250,570,250)+T(450,280,'Generation (0–20)',13)+T(450,25,'Frequency of allele A',17)+T(315,65,'1',12)+T(315,255,'0',12);let path=history.map((v,i)=>(i?'L':'M')+(335+i*11.5)+' '+(250-v*190)).join('');c+=`<path d="${path}" fill="none" stroke="#CC8A00" stroke-width="3"/>`;display(c,'Genotype symbols and allele A frequency over generations',`Generation ${gen} | A ${(p*100).toFixed(1)}% | a ${((1-p)*100).toFixed(1)}%`, 'Variation exists at the start. The selected environment changes relative reproductive success, then random mating produces the next generation. Switch the environment mid-run to reverse the selective advantage. A neutral environment preserves allele frequency in this deterministic model.','Large-population, one-locus model; no mutation, migration or genetic drift. AA/Aa/aa fitness is 1, 1−s/2, 1−s when A is favoured (reversed for a). Dots are rounded expected proportions, not individual organisms changing colour.');Q('#exStep').disabled=gen>=20;}

function pause(){clearInterval(timer);timer=null;Q('#exPlay').textContent='▶ Play generations';}function next(){if(gen<20){p=M.selection(p,state.selection,state.environment);gen++;history.push(p);evolution()}if(gen>=20)pause();}
Q('#exStep').onclick=()=>{pause();next()};Q('#exPlay').onclick=()=>{if(timer){pause();return}if(gen>=20){gen=0;p=.5;history=[.5]}Q('#exPlay').textContent='Ⅱ Pause';timer=setInterval(next,700)};Q('#exReset').onclick=()=>{pause();gen=0;p=.5;history=[.5];evolution()};Q('#ex-environment').onchange=e=>{pause();state.environment=e.target.value;evolution()};Q('#ex-selection').oninput=e=>{pause();state.selection=+e.target.value;Q('#selectionValue').textContent=e.target.value;evolution()};Q('#exQuiz').onclick=()=>{pause();window.dispatchEvent(new CustomEvent('science-exam-topic',{detail:'evolution'}))};if(reduce.matches){Q('#exPlay').disabled=true;Q('#exPlay').textContent='Reduced motion · use steps'}document.addEventListener('visibilitychange',()=>{if(document.hidden)pause()});window.addEventListener('science-model-topic',e=>{if(e.detail==='evolution')root.scrollIntoView({behavior:reduce.matches?'auto':'smooth'})});evolution();})();